      "id": "story.world_return",
      "tiers": [
        {
          "id": "story.world_return:t1",
          "title": "Мир припас тапочки",
          "phrase": "Один сюжетный архетип встретился тебе в 2 разных календарных месяцах. Этот мир уже припас для тебя тапочки.",
          "imagePrompt": "A tiny cottage with an open-book roof leans forward, offering oversized slippers through its doorway with two gloved hands; two blank calendar leaves curl around the doorstep like arriving visitors.",
          "fishMarkup": "[warm] Один сюжетный архетип встретился тебе в 2 разных календарных месяцах. [playful] Этот мир уже припас для тебя тапочки.",
          "audioText": "Один сюжетный архетип встретился тебе в 2 разных календарных месяцах. Этот мир уже припас для тебя тапочки."
        },
        {
          "id": "story.world_return:t2",
          "title": "Кресло за тобой",
          "phrase": "У тебя уже 4 разных календарных месяца с одним сюжетным архетипом. В этом мире твоё кресло больше никому не выдают.",
          "imagePrompt": "The little open-book-roof cottage uses both gloved hands to install a plush armchair on its expanding porch; slippers wait beneath the seat, while four blank calendar leaves fan out above the doorway.",
          "fishMarkup": "[confident] У тебя уже 4 разных календарных месяца с одним сюжетным архетипом. [playful] В этом мире <emphasis>твоё кресло</emphasis> больше никому не выдают.",
          "audioText": "У тебя уже 4 разных календарных месяца с одним сюжетным архетипом. В этом мире твоё кресло больше никому не выдают."
        },
        {
          "id": "story.world_return:t3",
          "title": "Мир с чемоданом",
          "phrase": "Один сюжетный архетип встретился тебе в 8 разных календарных месяцах. Теперь мир пришёл к тебе с чемоданом — пожить.",
          "imagePrompt": "The open-book-roof cottage stands in enormous slippers outside a much larger apartment door, knocking with one gloved hand and gripping a bulging suitcase with the other; blank calendar leaves poke out of its luggage.",
          "fishMarkup": "[triumphant] Один сюжетный архетип встретился тебе в 8 разных календарных месяцах. [playful] Теперь мир пришёл к тебе с чемоданом <slow>— пожить.</slow>",
          "audioText": "Один сюжетный архетип встретился тебе в 8 разных календарных месяцах. Теперь мир пришёл к тебе с чемоданом — пожить."
        }
      ]
    },
    {
      "id": "story.world_chapters",
      "tiers": [
        {
          "id": "story.world_chapters:t1",
          "title": "Театр на три мира",
          "phrase": "Ты собрал 1 триптих: минимум по 3 дня в каждом из 3 разных сюжетных архетипов. У твоего театра миров уже три сцены.",
          "imagePrompt": "A small stagehand crab unfolds a single hinged triptych stage with its claws; the panels contain a forest, a rolling sea and a mountain pass, each reached by a neat trail of three stepping stones.",
          "fishMarkup": "[warm] Ты собрал 1 триптих: минимум по 3 дня в каждом из 3 разных сюжетных архетипов. [playful] У твоего театра миров уже <emphasis>три сцены.</emphasis>",
          "audioText": "Ты собрал 1 триптих: минимум по 3 дня в каждом из 3 разных сюжетных архетипов. У твоего театра миров уже три сцены."
        },
        {
          "id": "story.world_chapters:t2",
          "title": "Битва за гримёрку",
          "phrase": "Теперь у тебя 2 триптиха; для каждого — минимум по 3 дня в каждом из 3 разных сюжетных архетипов. Сюжеты уже спорят за гримёрку.",
          "imagePrompt": "The stagehand crab balances two open triptych stages on opposite sides of a tiny dressing table; each stage holds forest, sea and mountain scenery, and both sets of curtains tug toward the same mirror.",
          "fishMarkup": "[confident] Теперь у тебя 2 триптиха; для каждого — минимум по 3 дня в каждом из 3 разных сюжетных архетипов. [playful] Сюжеты уже спорят за <emphasis>гримёрку.</emphasis>",
          "audioText": "Теперь у тебя 2 триптиха; для каждого — минимум по 3 дня в каждом из 3 разных сюжетных архетипов. Сюжеты уже спорят за гримёрку."
        },
        {
          "id": "story.world_chapters:t3",
          "title": "Чайник возглавил многомирье",
          "phrase": "У тебя 3 триптиха: в каждом — минимум по 3 дня в каждом из 3 разных сюжетных архетипов. Многомирье требует главного, и ты назначаешь чайник.",
          "imagePrompt": "The stagehand crab hoists a steaming kettle into a tall director's chair amid three open triptych stages, each containing forest, sea and mountain scenes; the crab solemnly offers the kettle a megaphone.",
          "fishMarkup": "[triumphant] У тебя 3 триптиха: в каждом — минимум по 3 дня в каждом из 3 разных сюжетных архетипов. [playful] Многомирье требует главного, <slow>и ты назначаешь</slow> <emphasis>чайник.</emphasis>",
          "audioText": "У тебя 3 триптиха: в каждом — минимум по 3 дня в каждом из 3 разных сюжетных архетипов. Многомирье требует главного, и ты назначаешь чайник."
        }
      ]
    }
  ]
}
